 * A CliError carries a fully formed message (without the trailing newline
 * and without any "error: " prefix decisions left to the caller) plus the
 * process exit code it should trigger.
 */
export class CliError extends Error {
  constructor(message, code) {
    super(message)
    this.code = code
  }
}

export function usageError() {
  return new CliError('usage: cli.js waves|explain|pack <workers>', 2)
}

export function workersError() {
  return new CliError('workers must be a positive integer', 2)
}

export function lineError(line, message) {
  return new CliError(`line ${line}: ${message}`, 2)
}

export function unknownTaskError(name) {
  return new CliError(`unknown task ${name}`, 2)
}

export function cycleError(names) {
  return new CliError(`cycle: ${names.join(' -> ')}`, 3)
}
"}

