const NAME_RE = /^[A-Za-z0-9_.-]+$/
const COST_RE = /^[0-9]+$/

/**
 * Parses the build graph description read from standard input.
 *
 * Returns { tasks, adjacency } where tasks maps name -> cost and adjacency
 * maps name -> Set of dependency names (edges only, no cycle checking).
 */
export function parseGraph(input) {
  let lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') {
    lines.pop()
  }

  const tasks = new Map()
  const depDirectives = []

  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const words = trimmed.split(/\s+/)
    const directive = words[0]

    if (directive === 'task') {
      if (words.length !== 3) {
        throw lineError(lineNo, 'expected task <name> <cost>')
      }
      const [, name, costStr] = words
      if (!NAME_RE.test(name)) {
        throw lineError(lineNo, `invalid task name ${name}`)
      }
      if (!COST_RE.test(costStr)) {
        throw lineError(lineNo, 'cost must be a non-negative integer')
      }
      if (tasks.has(name)) {
        throw lineError(lineNo, `task ${name} is declared twice`)
      }
      const cost = parseInt(costStr, 10)
      tasks.set(name, cost)
    } else if (directive === 'dep') {
      if (words.length < 3) {
        throw lineError(lineNo, 'expected dep <name> <dependency>...')
      }
      const target = words[1]
      const deps = words.slice(2)
      if (!NAME_RE.test(target)) {
        throw lineError(lineNo, `invalid task name ${target}`)
      }
      for (const dep of deps) {
        if (!NAME_RE.test(dep)) {
          throw lineError(lineNo, `invalid task name ${dep}`)
        }
      }
      depDirectives.push({ target, deps })
    } else {
      throw lineError(lineNo, `unknown directive ${directive}`)
    }
  }

  const adjacency = new Map()
  for (const { target, deps } of depDirectives) {
    if (!tasks.has(target)) {
      throw unknownTaskError(target)
    }
    for (const dep of deps) {
      if (!tasks.has(dep)) {
        throw unknownTaskError(dep)
      }
    }
    let set = adjacency.get(target)
    if (!set) {
      set = new Set()
      adjacency.set(target, set)
    }
    for (const dep of deps) {
      set.add(dep)
    }
  }

  return { tasks, adjacency }
}
"}

