{"file_path":"/tmp/claude-0/-home-user-deepseek-harness/f53f80cc-1f77-5d02-a862-99d59ffabdce/scratchpad/bench/runs/e3-attempts-t5/cell-Bi4fSc/src/graph.js","content":"import { cycleError } from './errors.js'

/**
 * Detects a cycle by running a depth-first search from each task in
 * ascending name order, walking each task's dependencies in ascending
 * name order. Throws a CliError describing the first cycle found, or
 * does nothing when the graph is acyclic.
 */
export function checkAcyclic(tasks, adjacency) {
  const names = [...tasks.keys()].sort()
  const color = new Map(names.map((n) => [n, 0])) // 0 white, 1 gray, 2 black
  const stack = []

  function visit(node) {
    color.set(node, 1)
    stack.push(node)
    const deps = [...(adjacency.get(node) || [])].sort()
    for (const dep of deps) {
      const c = color.get(dep)
      if (c === 1) {
        const idx = stack.indexOf(dep)
