/**
 * Simulates the build graph on a fixed number of workers, greedily picking
 * the highest-priority ready task (ties broken by ascending name) for the
 * lowest-index free worker at each instant.
 *
 * Returns { runs, makespan } where runs is an array (one per worker) of
 * { name, start, finish } entries in the order they ran.
 */
export function packSchedule(tasks, adjacency, workerCount) {
  const priorities = computePriorities(tasks, adjacency)
  const names = [...tasks.keys()]
  const total = names.length

  const runs = Array.from({ length: workerCount }, () => [])
  const workerFree = new Array(workerCount).fill(0)

  const finish = new Map()
  const started = new Set()

  let time = 0
  let makespan = 0

  while (started.size < total) {
    let progressed = true
    while (progressed) {
      progressed = false

      let freeIdx = -1
      for (let i = 0; i < workerCount; i++) {
        if (workerFree[i] <= time) {
          freeIdx = i
          break
        }
      }
      if (freeIdx === -1) break

      let best = null
      for (const name of names) {
        if (started.has(name)) continue
        const deps = adjacency.get(name)
        let ready = true
        if (deps) {
          for (const dep of deps) {
            if (!finish.has(dep) || finish.get(dep) > time) {
              ready = false
              break
            }
          }
        }
        if (!ready) continue
        if (
          best === null ||
          priorities.get(name) > priorities.get(best) ||
          (priorities.get(name) === priorities.get(best) && name < best)
        ) {
          best = name
        }
      }
      if (best === null) break

      const start = time
      const f = start + tasks.get(best)
      workerFree[freeIdx] = f
      finish.set(best, f)
      started.add(best)
      runs[freeIdx].push({ name: best, start, finish: f })
      if (f > makespan) makespan = f
      progressed = true
    }

    if (started.size >= total) break

    let next = Infinity
    for (let i = 0; i < workerCount; i++) {
      if (workerFree[i] > time && workerFree[i] < next) next = workerFree[i]
    }
    if (!Number.isFinite(next)) {
      // Should not happen for an acyclic, fully-validated graph.
      break
    }
    time = next
  }

  return { runs, makespan }
}
"}

