/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { parseGraph } from './parse.js'
import { checkAcyclic, computeTimings } from './graph.js'
import { packSchedule } from './pack.js'
import { CliError, usageError, workersError } from './errors.js'

function readStdin() {
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!/^[1-9][0-9]*$/.test(argv[1])) {
      throw workersError()
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw usageError()
}

function renderWaves(tasks, timings) {
  const out = []
  const byDepth = new Map()
  for (const [name, info] of timings) {
    if (!byDepth.has(info.depth)) byDepth.set(info.depth, [])
    byDepth.get(info.depth).push(name)
  }
  const depths = [...byDepth.keys()].sort((a, b) => a - b)
  for (const depth of depths) {
    const names = byDepth.get(depth).sort()
    out.push(`wave ${depth}: ${names.join(' ')}`)
  }
  let total = 0
  for (const info of timings.values()) {
    if (info.finish > total) total = info.finish
  }
  out.push(`total ${total}`)
  return out.join('\n') + '\n'
}

function renderExplain(tasks, timings) {
  const out = []
  const names = [...tasks.keys()].sort()
  for (const name of names) {
    const info = timings.get(name)
    out.push(`${name} start=${info.start} finish=${info.finish} depth=${info.depth}`)
