/**
 * The command. `node src/cli.js waves`, `node src/cli.js explain` and
 * `node src/cli.js pack <workers>` each report on the build graph read from
 * standard input.
 */

import { readFileSync } from 'node:fs'
import { parseGraph } from './parse.js'
import { checkAcyclic, computeTimings } from './graph.js'
import { packSchedule } from './pack.js'
import { CliError, usageError, workersError } from './errors.js'

function readStdinSync() {
  return readFileSync(0, 'utf8')
}

function parseArgs(argv) {
  if (argv.length === 1 && (argv[0] === 'waves' || argv[0] === 'explain')) {
    return { mode: argv[0] }
  }
  if (argv.length === 2 && argv[0] === 'pack') {
    if (!/^[1-9][0-9]*$/.test(argv[1])) {
      throw workersError()
    }
    return { mode: 'pack', workers: parseInt(argv[1], 10) }
  }
  throw usageError()
}

function renderWaves(tasks, timings) {
  const out = []
  const byDepth = new Map()
  for (const [name, info] of timings) {
    if (!byDepth.has(info.depth)) byDepth.set(info.depth, [])
    byDepth.get(info.depth).push(name)
  }
  const depths = [...byDepth.keys()].sort((a, b) => a - b)
  for (const depth of depths) {
    const names = byDepth.get(depth).sort()
    out.push(`wave ${depth}: ${names.join(' ')}`)
  }
  let total = 0
  for (const info of timings.values()) {
    if (info.finish > total) total = info.finish
  }
  out.push(`total ${total}`)
  return out.join('\n') + '\n'
}

function renderExplain(tasks, timings) {
  const out = []
  const names = [...tasks.keys()].sort()
  for (const name of names) {
    const info = timings.get(name)
    out.push(`${name} start=${info.start} finish=${info.finish} depth=${info.depth}`)
  }
  let total = 0
  for (const info of timings.values()) {
    if (info.finish > total) total = info.finish
  }
  out.push(`total ${total}`)
  return out.join('\n') + '\n'
}

function renderPack(runs, makespan) {
  const out = []
  for (let i = 0; i < runs.length; i++) {
    const parts = runs[i].map((r) => `${r.name}@${r.start}-${r.finish}`)
    out.push(`worker ${i}:${parts.length ? ' ' + parts.join(' ') : ''}`)
  }
  out.push(`makespan ${makespan}`)
  return out.join('\n') + '\n'
}

function main() {
  const argv = process.argv.slice(2)
  const args = parseArgs(argv)

  const input = readStdinSync()
  const { tasks, adjacency } = parseGraph(input)
  checkAcyclic(tasks, adjacency)

  if (args.mode === 'waves') {
    const timings = computeTimings(tasks, adjacency)
    process.stdout.write(renderWaves(tasks, timings))
  } else if (args.mode === 'explain') {
    const timings = computeTimings(tasks, adjacency)
    process.stdout.write(renderExplain(tasks, timings))
  } else if (args.mode === 'pack') {
    const { runs, makespan } = packSchedule(tasks, adjacency, args.workers)
    process.stdout.write(renderPack(runs, makespan))
  }
}

try {
  main()
} catch (err) {
  if (err instanceof CliError) {
    process.stderr.write(`error: ${err.message}\n`)
    process.exit(err.code)
  }
  throw err
}
